-- Import des courriers arrivées 2008
-- Source : 2008.xlsx (feuille 2008).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N°                -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE CREATION     -> dt_datearrivee et dt_datecourier
--   PRENOMS + NOM     -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS      -> txt_objet (libellé d'origine)
--   DESIGNATIONS      -> txt_designation (liste designationsParCategorie)
--   designation retenue -> txt_categorie
--   N° TF             -> txt_numTitreFoncier
--   N° LOT            -> txt_numLot
--   AGENTS TRAITEURS  -> txt_agenttraiteur
--   OBSERVATIONS      -> txt_observation
--   CATEGORIES        -> ignorée (toujours Demande SERVICES) ; la catégorie vient de la désignation
--   référence formulaire -> « <N°> du jj-mm-aaaa »
--   NICAD cité dans l'objet -> txt_NICAD
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates d'arrivée illisibles reconstituées sur la ligne voisine : 13
-- Lignes importées : 1738
-- Lignes non importées :
--   ligne Excel 572 : N° 464 sans objet, nom ni titre
--   ligne Excel 589 : N° 481 sans objet, nom ni titre
--   ligne Excel 607 : N° 499 sans objet, nom ni titre
--   ligne Excel 1097 : N° 899 sans objet, nom ni titre
--
-- Répartition des catégories :
--    1670  Demande SERVICES
--      55  Information
--      10  Convocation - Invitation
--       3  Réclamation - Signalement
-- Désignations :
--     610  Morcellements
--     385  Autorisation de construction
--     209  Demande de Cession définitive
--     202  Demande de Régularisation par voie de Bail
--      69  Demande de terrain/Echange
--      51  Demande de délimitation
--      33  Litiges
--      27  Autorisation de lotir
--      19  Autres
--      19  Duplication de CIC
--      14  Demande d'états des lieux
--      11  Demande d'évaluation
--      11  Note de service
--       9  Demande de situation foncière
--       8  Demande de Titre foncier
--       7  Circulaire
--       7  Réunion
--       7  Rapport
--       6  Demande d'extraits de plan
--       6  Réceptions de lotissements
--       5  Réquisition d'immatriculation
--       4  Tribunal
--       4  Décision - Arrêté
--       3  Plainte
--       2  Transmission lettre
--       2  Formation
--       2  PV - Compte - rendu
--       2  Lettre
--       1  Texte juridique
--       1  Séminaire
--       1  Autorisation de morceler
--       1  Demande de reconstruction

SET NAMES utf8mb4;

-- Certains N° TF du classeur dépassent 25 caractères (listes de titres).
ALTER TABLE `arrivees`
  MODIFY `txt_numTitreFoncier` VARCHAR(255) NULL,
  MODIFY `txt_numTitreMere` VARCHAR(255) NULL;

START TRANSACTION;






COMMIT;
